qsa("[data-open-inventory-form]").forEach(b=>b.addEventListener("click",()=>openInventoryDialog()));
qsa("[data-open-catalog-form]").forEach(b=>b.addEventListener("click",()=>openCatalogDialog()));
qs("#search-input").addEventListener("input",loadPortfolio);
qs("#filter-select").addEventListener("change",loadPortfolio);
