async function loadVertexQuotes(){const rail=qs("#vertex-tickers");if(!rail)return;rail.innerHTML='<div class="market-state market-state--loading"><span class="loading-bar"></span><span>Loading market data...</span></div>';try{const d=await api("/api/market/quotes?symbols=AAPL,MSFT,NVDA,GOOGL,AMZN");if(!d.quotes?.length){rail.innerHTML='<div class="market-state">No market data available.</div>';return}rail.innerHTML=d.quotes.map(q=>`<div class="ticker"><b>${q.symbol}</b><small>$${q.price.toFixed(2)}</small><span class="${q.change_percent>=0?"up":"down"}">${q.change_percent>=0?"+":""}${q.change_percent.toFixed(2)}%</span></div>`).join("")+`<div class="ticker"><small>${d.quotes.some(q=>q.source==="fallback")?"DELAYED":"DELAYED"}</small></div>`}catch{rail.innerHTML='<div class="market-state market-state--error"><strong>Unable to load market data.</strong><span>We\'re showing the latest available cached data.</span><button type="button" data-retry-quotes>Retry</button></div>';rail.querySelector("[data-retry-quotes]")?.addEventListener("click",loadVertexQuotes)}}
function setupVertexGlobalSearch(){const input=qs("#vertex-search");if(!input)return;const replacement=input.cloneNode(true);input.replaceWith(replacement);let timer;let controller;replacement.addEventListener("input",()=>{clearTimeout(timer);controller?.abort();const query=replacement.value.trim();const results=qs("[data-search-results]");if(query.length<1){results.innerHTML="";return}results.innerHTML='<div class="vi-result vi-result--loading">Searching global markets...</div>';timer=window.setTimeout(async()=>{controller=new AbortController();try{const data=await api(`/api/stock-search?query=${encodeURIComponent(query)}`,{signal:controller.signal});const items=data.results||[];results.innerHTML=items.length?items.map(item=>`<button type="button" class="vi-result" data-symbol="${escapeHtml(item.symbol)}"><span><b>${escapeHtml(item.symbol)}</b><small>${escapeHtml(item.name)} · ${escapeHtml(item.market||"Global")}</small></span><strong>${item.current_price?rupee.format(item.current_price):"View quote"}</strong></button>`).join(""):"<div class=\"vi-result vi-result--empty\">No matching global instruments</div>";qsa(".vi-result[data-symbol]").forEach(button=>button.addEventListener("click",()=>{location.href=`/stock?symbol=${encodeURIComponent(button.dataset.symbol)}`}))}catch(error){if(error.name!=="AbortError")results.innerHTML='<div class="vi-result vi-result--empty">Search is temporarily unavailable</div>'}},160)});replacement.addEventListener("keydown",event=>{if(event.key==="Escape"){replacement.value="";qs("[data-search-results]").innerHTML=""}if(event.key==="Enter"&&qs(".vi-result[data-symbol]")){event.preventDefault();qs(".vi-result[data-symbol]").click()}})}
