function enhanceVertexSearchResults(){const input=qs("#vertex-search"),results=qs("[data-search-results]");if(!input||!results||results.dataset.powerSearch)return;results.dataset.powerSearch="true";const topics={apple:["Apple suppliers","Technology","Consumer electronics"],aapl:["Apple suppliers","Technology","Consumer electronics"],tesla:["EVs","Clean energy","Automotive"],nvidia:["AI","Semiconductors","Data centers"],microsoft:["Cloud computing","Enterprise software","Technology"]};const decorate=()=>{const buttons=[...results.querySelectorAll(".vi-result[data-symbol]")];if(!buttons.length||results.querySelector(".vi-search-heading"))return;const query=input.value.trim().toLowerCase(),related=topics[query]||topics[Object.keys(topics).find(key=>query.includes(key))]||[];const heading=document.createElement("div");heading.className="vi-search-heading";heading.textContent="Search results";results.prepend(heading);if(related.length){const group=document.createElement("div");group.className="vi-related-search";group.innerHTML=`<small>Related</small>${related.map(topic=>`<button type="button" data-related-search="${escapeHtml(topic)}">${escapeHtml(topic)}</button>`).join("")}`;results.appendChild(group);group.querySelectorAll("[data-related-search]").forEach(button=>button.addEventListener("click",()=>{input.value=button.dataset.relatedSearch;input.dispatchEvent(new Event("input",{bubbles:true}))}))}};new MutationObserver(decorate).observe(results,{childList:true,subtree:true});input.addEventListener("keydown",event=>{const items=[...results.querySelectorAll(".vi-result[data-symbol]")];if(!items.length)return;const current=items.indexOf(document.activeElement);if(event.key==="ArrowDown"||event.key==="ArrowUp"){event.preventDefault();items[(current+(event.key==="ArrowDown"?1:-1)+items.length)%items.length].focus()}if(event.key==="Enter"&&document.activeElement?.matches(".vi-result[data-symbol]")){event.preventDefault();document.activeElement.click()}})}
