function setupVertexSimulatorControls(){let selected="AAPL",years=5;const update=()=>{const amount=Math.min(100000,Math.max(100,Number(qs("#sim-amount").value)||100));qs("#sim-amount").value=amount;qs("#sim-range").value=amount;const percent=vertexReturn(selected,years);qs("#sim-company").innerHTML=`${VERTEX_COMPANIES[selected]?.name||selected} <small>${selected}</small>`;qs("#sim-chart").innerHTML=vertexHistory[selected]?vertexChartFromHistory(selected,years):vertexChart(selected,years);qs("#sim-range-label").textContent=vertexMoney.format(amount);qs("#sim-value").textContent=vertexMoney.format(amount*(1+percent/100));qs("#sim-return").textContent=`${percent>=0?"+":""}${percent.toFixed(1)}%`};refreshVertexSimulator=update;qsa("[data-company]").forEach(button=>{const replacement=button.cloneNode(true);button.replaceWith(replacement)});qsa("[data-years]").forEach(button=>{const replacement=button.cloneNode(true);button.replaceWith(replacement)});qsa("[data-company]").forEach(button=>button.addEventListener("click",()=>{selected=button.dataset.company;qsa("[data-company]").forEach(item=>{item.classList.toggle("active",item===button);item.setAttribute("aria-selected",item===button)});update();loadVertexHistory(selected)}));qsa("[data-years]").forEach(button=>button.addEventListener("click",()=>{years=Number(button.dataset.years);qsa("[data-years]").forEach(item=>item.classList.toggle("active",item===button));update()}));["#sim-range","#sim-amount"].forEach(selector=>{const input=qs(selector);const replacement=input.cloneNode(true);input.replaceWith(replacement);qs(selector).addEventListener("input",event=>{qs(selector==="#sim-range"?"#sim-amount":"#sim-range").value=event.target.value;update()})});update()}
function renderVertexExplorer(){const main=qs("#global-investing-page main");if(!main||qs("#vertex-explorer"))return;main.insertAdjacentHTML("afterbegin",`<section id="vertex-explorer" class="vi-explorer"><div class="vi-explorer__head"><div><span class="vi-kicker">Global market map</span><h2>Find a company worth revisiting</h2><p>Search symbols and company names across supported markets, then open any instrument in the sandbox terminal.</p></div><div class="vi-region-tabs" role="tablist"><button class="active" data-region="Featured">Featured</button><button data-region="India">India</button><button data-region="United States">United States</button><button data-region="Europe">Europe</button><button data-region="Asia">Asia</button></div></div><div class="vi-explorer__body"><div id="vi-explorer-grid" class="vi-explorer__grid"><div class="vi-loading">Loading market map...</div></div><aside id="vi-explorer-detail" class="vi-explorer__detail"><span class="vi-detail-kicker">Pick an instrument</span><h3>Markets at a glance</h3><p>Select a card to see its delayed quote and open a practice terminal.</p></aside></div></section>`);const regionSymbols={Featured:["AAPL","MSFT","NVDA","RELIANCE","TSM","ASML"],India:["RELIANCE","TCS","INFY","HDFC","ICICIBANK","TATAMOTORS"],"United States":["AAPL","MSFT","NVDA","AMZN","META","TSLA"],Europe:["ASML","SAP","SIEGY","NESN.SW","MC.PA","AZN"],Asia:["TSM","TM","SONY","TCEHY","BABA","9988.HK"]};let activeRegion="Featured";const load=async()=>{const grid=qs("#vi-explorer-grid");grid.innerHTML='<div class="vi-loading">Refreshing delayed quotes...</div>';const symbols=regionSymbols[activeRegion];try{const data=await api(`/api/market/quotes?symbols=${symbols.slice(0,8).join(",")}`);grid.innerHTML=data.quotes.map(quote=>`<button class="vi-market-card" data-explorer-symbol="${escapeHtml(quote.symbol)}"><span class="vi-market-card__top"><b>${escapeHtml(quote.symbol)}</b><span class="${quote.change_percent>=0?"gain":"loss"}">${quote.change_percent>=0?"+":""}${quote.change_percent.toFixed(2)}%</span></span><strong>${quote.currency==="USD"?"$":""}${quote.price.toFixed(2)}</strong><small>${escapeHtml(quote.name)} · ${escapeHtml(quote.source==="fallback"?"Delayed fallback":"Delayed quote")}</small></button>`).join("");qsa("[data-explorer-symbol]").forEach(card=>card.addEventListener("click",()=>{const quote=data.quotes.find(item=>item.symbol===card.dataset.explorerSymbol);const detail=qs("#vi-explorer-detail");detail.innerHTML=`<span class="vi-detail-kicker">Selected instrument</span><h3>${escapeHtml(quote.name)} <small>${escapeHtml(quote.symbol)}</small></h3><div class="vi-detail-price">$${quote.price.toFixed(2)} <span class="${quote.change_percent>=0?"gain":"loss"}">${quote.change_percent>=0?"+":""}${quote.change_percent.toFixed(2)}%</span></div><p>Delayed quote from ${quote.source==="fallback"?"the local fallback feed":"the market data provider"}. Explore price history or practise this symbol without placing a real order.</p><a class="vi-cta" href="/terminal?symbol=${encodeURIComponent(quote.symbol)}">Open in sandbox</a>`}))}catch{grid.innerHTML='<div class="vi-loading">Market data is temporarily unavailable.</div>'}};qsa("[data-region]").forEach(button=>button.addEventListener("click",()=>{activeRegion=button.dataset.region;qsa("[data-region]").forEach(item=>item.classList.toggle("active",item===button));load()}));load()}
function decorateVertexMarketCards(){qsa(".vi-market-card").forEach(card=>{if(card.dataset.decorated)return;const top=card.querySelector(".vi-market-card__top"),symbol=top?.querySelector("b")?.textContent.trim()||"?",change=top?.querySelector("span")?.textContent.trim()||"",price=card.querySelector("strong")?.textContent.trim()||"",meta=card.querySelector("small")?.textContent.split(" · ")||[];if(!top)return;top.innerHTML=`<span class="vi-market-card__identity"><span class="vi-market-card__logo">${escapeHtml(symbol.slice(0,1))}</span><b>${escapeHtml(symbol)}</b></span><span class="${change.startsWith("-")?"loss":"gain"}">${escapeHtml(change)}</span>`;const small=card.querySelector("small");if(small)small.innerHTML=`<span>${escapeHtml(meta[0]||"Global company")}</span><span>${escapeHtml(meta[1]||"Delayed quote")}</span>`;card.dataset.decorated="true"})}
async function renderVertexPulse(){const explorer=qs("#vertex-explorer");if(!explorer||qs("#vi-market-pulse"))return;explorer.insertAdjacentHTML("afterend",'<section id="vi-market-pulse" class="vi-market-pulse"><div class="vi-market-pulse__head"><div><span class="vi-kicker">Markets at a glance</span><h2>Track the names moving your watchlist</h2></div><span class="vi-market-pulse__status">Delayed quotes · refreshed now</span></div><div id="vi-market-pulse-grid" class="vi-market-pulse__grid"><div class="vi-loading">Loading market pulse...</div></div></section>');try{const data=await api("/api/market/quotes?symbols=AAPL,MSFT,NVDA");const grid=qs("#vi-market-pulse-grid");grid.innerHTML=data.quotes.map(quote=>{const positive=quote.change_percent>=0;const width=Math.min(100,Math.max(12,50+quote.change_percent*12));return`<article class="vi-pulse-card"><div class="vi-pulse-card__top"><span><b>${escapeHtml(quote.symbol)}</b><small>${escapeHtml(quote.name)}</small></span><strong class="${positive?"gain":"loss"}">${positive?"+":""}${quote.change_percent.toFixed(2)}%</strong></div><div class="vi-pulse-price">$${quote.price.toFixed(2)}</div><div class="vi-pulse-bar"><span class="${positive?"gain":"loss"}" style="width:${width}%"></span></div><small>${quote.delayed?"Delayed quote":"Market quote"}</small></article>`}).join("")}catch{const grid=qs("#vi-market-pulse-grid");if(grid)grid.innerHTML='<div class="vi-loading">Market pulse is temporarily unavailable.</div>'}}
