function terminalChart(symbol,timeframe){const settings={"1D":[30,1.18],"5D":[48,1.71],"1M":[58,.72],"1Y":[64,.31]}[timeframe]||[48,1.71];const [count,frequency]=settings,seed=symbol.split("").reduce((a,c)=>a+c.charCodeAt(0),0)+timeframe.length*17;let price=160+(seed%90);const candles=Array.from({length:count},(_,i)=>{const open=price;price+=Math.sin(i*frequency+seed)*4+(i%7===0?-5:1);const close=price,high=Math.max(open,close)+3+(i%5),low=Math.min(open,close)-3-(i%4);return{open,close,high,low}}),max=Math.max(...candles.map(x=>x.high)),min=Math.min(...candles.map(x=>x.low)),y=x=>315-((x-min)/(max-min))*280,step=720/count;return `<svg class="candle-chart" viewBox="0 0 760 340" role="img" aria-label="Simulated ${symbol} ${timeframe} candlestick chart"><path d="M0 66H760M0 132H760M0 198H760M0 264H760" stroke="#1b2424"/>${candles.map((c,i)=>{const x=20+i*step,w=Math.max(3,step*.52),green=c.close>=c.open;return `<line x1="${x+w/2}" y1="${y(c.high)}" x2="${x+w/2}" y2="${y(c.low)}" stroke="${green?"#9fe0cd":"#ee7264"}"/><rect x="${x}" y="${Math.min(y(c.open),y(c.close))}" width="${w}" height="${Math.max(2,Math.abs(y(c.open)-y(c.close)))}" fill="${green?"#9fe0cd":"#ee7264"}"/>`}).join("")}<path d="M0 258 ${candles.map((c,i)=>`L${20+i*step+step*.25} ${y((c.open+c.close)/2)}`).join(" ")}" fill="none" stroke="#8c55c9" stroke-width="2"/></svg>`}
